const initialState=()=>({schemaVersion:SAVE_SCHEMA,day:1,gold:120,reputation:10,ale:20,food:12,prices:{ale:4,meal:7},upgrades:{tables:1,kitchen:1,cellar:1,decor:1,rooms:0},forecast:makeForecast(),staff:[makeWorker(ELENA_BASE,{id:'elena-main',level:3,morale:82,loyalty:68})],candidates:['luna','kaia','mira'],selectedWorkerId:'elena-main',financeHistory:[],customerHistory:[],regulars:[],lifetime:{customers:0,revenue:0,profit:0,expenses:0},lastDay:null,log:[{day:0,title:'Llegas a Brumavieja',text:'Has heredado una taberna pequeña. Elena, una camarera local, acepta ayudarte a ponerla en marcha.'}]});
let state=load(),toastTimer,modalAction=null;
