function loadTrainerSettings(){try{const raw=localStorage.getItem(TRAINER_KEY);const x=raw?JSON.parse(raw):{};return{infiniteEnergy:!!x.infiniteEnergy}}catch{return{infiniteEnergy:false}}}
function saveTrainerSettings(){localStorage.setItem(TRAINER_KEY,JSON.stringify(trainerSettings))}
function trainerInfinite(){return!!trainerSettings.infiniteEnergy}
function applyInfiniteEnergy(){if(!trainerInfinite())return;for(const w of state.staff)w.energy=100}
function restoreSelectedEnergy(){const w=selectedWorker();if(!w)return false;w.energy=100;w.active=true;save();render();renderTrainer();toast(`${w.name}: energía restaurada al 100%`);return true}
function restoreAllEnergy(){if(!state.staff.length)return false;for(const w of state.staff){w.energy=100;w.active=true}save();render();renderTrainer();toast('Toda la plantilla está al 100% y disponible');return true}
function setInfiniteEnergy(enabled){trainerSettings.infiniteEnergy=!!enabled;if(trainerInfinite())applyInfiniteEnergy();saveTrainerSettings();save();render();renderTrainer();return trainerSettings.infiniteEnergy}
function renderTrainer(){const overlay=$('#trainerOverlay');if(!overlay)return;const w=selectedWorker(),energy=w?Math.round(w.energy||0):0,name=$('#trainerWorkerName'),status=$('#trainerWorkerStatus'),value=$('#trainerWorkerEnergy'),bar=$('#trainerWorkerEnergyBar'),toggle=$('#trainerInfiniteEnergy');if(name)name.textContent=w?.name||'Sin trabajadora';if(status)status.textContent=w?`${w.active?'Disponible':'Descansando'} · ${assignmentLabel(w.assignment)} · Energía ${energy}%`:'No hay personal';if(value)value.textContent=`${energy}%`;if(bar)bar.style.width=`${clamp(energy,0,100)}%`;if(toggle)toggle.checked=trainerInfinite()}
function openTrainer(){renderTrainer();const o=$('#trainerOverlay');if(!o)return false;o.classList.add('open');o.setAttribute('aria-hidden','false');document.body.classList?.add('trainer-open');return true}
function closeTrainer(){const o=$('#trainerOverlay');if(!o)return;o.classList.remove('open');o.setAttribute('aria-hidden','true');document.body.classList?.remove('trainer-open')}
function trainerSecretTap(){trainerTapCount++;clearTimeout(trainerTapTimer);trainerTapTimer=setTimeout(()=>{trainerTapCount=0},1600);if(trainerTapCount>=5){trainerTapCount=0;clearTimeout(trainerTapTimer);trainerTapTimer=null;openTrainer();return true}return false}
function catalogForWorker(w){const id=w.catalogId||String(w.id||'').split('-')[0];return id==='elena'?ELENA_BASE:CANDIDATE_CATALOG.find(c=>c.id===id)||CANDIDATE_CATALOG.find(c=>c.name===w.name)}
function migrate(parsed){const fresh=initialState();const s={...fresh,...parsed,schemaVersion:SAVE_SCHEMA,prices:{...fresh.prices,...(parsed.prices||{})},upgrades:{...fresh.upgrades,...(parsed.upgrades||{})},lifetime:{...fresh.lifetime,...(parsed.lifetime||{})},financeHistory:Array.isArray(parsed.financeHistory)?parsed.financeHistory:[],customerHistory:Array.isArray(parsed.customerHistory)?parsed.customerHistory:[],log:Array.isArray(parsed.log)?parsed.log:fresh.log};if(!Array.isArray(parsed.staff)){s.staff=[makeWorker(ELENA_BASE,{id:'elena-main',level:3,morale:82,loyalty:68})];const extraServers=Math.max(0,(Number(parsed.servers)||1)-1);const extraCooks=Math.max(0,Number(parsed.cooks)||0);for(let i=0;i<extraServers;i++)s.staff.push(makeWorker(CANDIDATE_CATALOG.find(x=>x.role==='server'),{id:`legacy-server-${i}`,name:`Camarera ${i+2}`}));for(let i=0;i<extraCooks;i++)s.staff.push(makeWorker(CANDIDATE_CATALOG.find(x=>x.role==='cook'),{id:`legacy-cook-${i}`,name:`Cocinera ${i+1}`}));s.log.unshift({day:s.day,title:'Partida migrada',text:'Tu progreso anterior se conservó y el personal fue convertido al nuevo sistema de personajes.'})}else{s.staff=parsed.staff.map(w=>{const base=catalogForWorker(w)||w;return makeWorker(base,{...w,catalogId:base.id||w.catalogId,portrait:base.portrait||w.portrait,sprite:base.sprite||w.sprite,wage:base.wage??w.wage,rarity:base.rarity||w.rarity,rarityClass:base.rarityClass||w.rarityClass,trait:base.trait||w.trait,ability:base.ability||w.ability,abilityId:base.abilityId||w.abilityId,abilityText:base.abilityText||w.abilityText,assignment:w.assignment||base.assignment,loyalty:w.loyalty??65,service:Math.max(w.service||0,base.service||0),charisma:Math.max(w.charisma||0,base.charisma||0),speed:Math.max(w.speed||0,base.speed||0),stamina:Math.max(w.stamina||0,base.stamina||0)})});if(parsed.schemaVersion<3)s.log.unshift({day:s.day,title:'Actualización V0.3',text:'La plantilla ahora tiene retratos, rareza, lealtad, habilidades y asignaciones de trabajo.'})}if((parsed.schemaVersion||0)<4)s.log.unshift({day:s.day,title:'Actualización V0.4',text:'La interfaz fue reconstruida como un centro de mando de gestión, conservando toda tu partida y personal.'});if((parsed.schemaVersion||0)<5)s.log.unshift({day:s.day,title:'Actualización V0.5',text:'La taberna ahora opera por puestos reales. Salón, barra, cocina, recepción y despensa afectan directamente cada jornada.'});if((parsed.schemaVersion||0)<6)s.log.unshift({day:s.day,title:'Actualización V0.6',text:'Las jornadas ahora se desarrollan en vivo con clientes individuales, esperas, propinas, eventos y dirección de personal durante el servicio.'});if(!Array.isArray(s.candidates)||!s.candidates.length)s.candidates=['luna','kaia','mira'];if(!Array.isArray(s.regulars))s.regulars=[];if(!s.selectedWorkerId||!s.staff.some(w=>w.id===s.selectedWorkerId))s.selectedWorkerId=s.staff[0]?.id||null;return s}
function load(){try{const raw=localStorage.getItem(SAVE_KEY);return raw?migrate(JSON.parse(raw)):initialState()}catch{return initialState()}}
function save(show=false){state.schemaVersion=SAVE_SCHEMA;localStorage.setItem(SAVE_KEY,JSON.stringify(state));if(show)toast('Partida guardada')}
const clamp=(n,min,max)=>Math.max(min,Math.min(max,n)),rand=(min,max)=>Math.floor(Math.random()*(max-min+1))+min,chance=p=>Math.random()<p;
function capacity(){return 6+state.upgrades.tables*4}function cellarSoftCap(){return 24+state.upgrades.cellar*16}function activeStaff(){return state.staff.filter(w=>w.active)}function staffAt(post){return activeStaff().filter(w=>w.assignment===post)}function servers(){return activeStaff().filter(w=>w.role==='server')}function cooks(){return activeStaff().filter(w=>w.role==='cook')}function wages(){return state.staff.reduce((a,w)=>a+w.wage,0)}function hasAbility(id){return activeStaff().some(w=>w.abilityId===id)}function workersWithAbility(id){return activeStaff().filter(w=>w.abilityId===id)}function postPower(post){return staffAt(post).reduce((a,w)=>a+workerEfficiency(w)*(w.service*.35+w.speed*.3+w.charisma*.2+w.stamina*.15),0)}function hasPost(post){return staffAt(post).length>0}function operationalReadiness(){const required=['salon','barra'];const missing=required.filter(p=>!hasPost(p));if(!hasPost('cocina'))missing.push('cocina');const score=clamp(100-missing.length*18+(hasPost('recepcion')?5:0)+(hasPost('despensa')?4:0),35,100);return{missing,score}}
function avg(arr,key){return arr.length?arr.reduce((a,x)=>a+x[key],0)/arr.length:0}function season(){const n=Math.floor((state.day-1)/30)%4;return['Primavera','Verano','Otoño','Invierno'][n]}
function workerEfficiency(w){const energy=.55+.45*(w.energy/100),morale=.7+.3*(w.morale/100),loyalty=.85+.15*((w.loyalty??60)/100),level=1+(w.level-1)*.04;return energy*morale*loyalty*level}
function serviceScore(customers){const sv=servers();const ck=cooks();const labor=sv.reduce((a,w)=>{const assign=w.assignment==='salon'?1.18:w.assignment==='barra'?1.08:w.assignment==='recepcion'?1.02:.9;const swift=w.abilityId==='swift'?1.12:1;return a+(w.service*.055+w.speed*.035)*workerEfficiency(w)*assign*swift},0)+ck.reduce((a,w)=>a+w.speed*.012*workerEfficiency(w),0)+state.upgrades.kitchen*1.45+(hasAbility('warm')?1.8:0);const coverage=(hasPost('salon')?1:0)+(hasPost('barra')?.6:0);return clamp(.4+coverage*.08+labor/Math.max(16,customers*2.6),.35,1.3)}
function kitchenPower(){const kitchen=staffAt('cocina'),all=cooks();return state.upgrades.kitchen*7+kitchen.reduce((a,w)=>a+(w.speed+w.stamina+(w.cooking||0)*.45)*.21*workerEfficiency(w),0)+all.filter(w=>w.assignment!=='cocina').reduce((a,w)=>a+(w.speed+w.stamina)*.05*workerEfficiency(w),0)+(hasAbility('mise')?4:0)}function hospitalityPower(){const reception=staffAt('recepcion'),floor=staffAt('salon');return reception.reduce((a,w)=>a+(w.charisma+w.service)*.22*workerEfficiency(w),0)+floor.reduce((a,w)=>a+(w.charisma+w.service)*.1*workerEfficiency(w),0)+state.upgrades.decor*4+(hasAbility('vip')?5:0)}
function demandModifier(){const a=Math.max(0,state.prices.ale-5)*.055,m=Math.max(0,state.prices.meal-8)*.04,cheap=(state.prices.ale<=3?.05:0)+(state.prices.meal<=6?.04:0),decor=1+(state.upgrades.decor-1)*.025;return clamp((1-a-m+cheap)*decor,.4,1.3)}
function log(title,text,day=state.day){state.log.unshift({day,title,text});state.log=state.log.slice(0,150)}
function upgradeCost(type){const base={tables:45,kitchen:55,cellar:50,decor:65,rooms:90}[type];const level=state.upgrades[type]||0;return Math.round(base*Math.max(1,level+(.35*(level>0))))}
function buy(kind,amount,cost,label){if(state.gold<cost)return toast('No tienes suficiente oro');if(state[kind]+amount>cellarSoftCap()+12)return toast('La bodega está demasiado llena');state.gold-=cost;state[kind]+=amount;log('Compra de provisiones',`${label}: +${amount}. Pagaste ${cost} de oro.`);save();render()}
function changePrice(kind,delta){const lim=kind==='ale'?[2,12]:[4,18];state.prices[kind]=clamp(state.prices[kind]+delta,...lim);save();render()}
function upgrade(type){const cost=upgradeCost(type);if(state.gold<cost)return toast(`Necesitas ${cost} de oro`);state.gold-=cost;state.upgrades[type]=(state.upgrades[type]||0)+1;const names={tables:'Mesas y bancos',kitchen:'Cocina',cellar:'Bodega',decor:'Decoración',rooms:'Habitaciones'};log('Mejora completada',`${names[type]} sube a nivel ${state.upgrades[type]}. Coste: ${cost} oro.`);save();render()}
function candidateById(id){return CANDIDATE_CATALOG.find(c=>c.id===id)}
function hireCandidate(id){const c=candidateById(id);if(!c)return;if(state.gold<c.hireCost)return toast('No tienes suficiente oro');state.gold-=c.hireCost;const w=makeWorker(c,{id:`${c.id}-${Date.now()}`,morale:rand(65,82),energy:100,loyalty:rand(55,72)});state.staff.push(w);state.candidates=state.candidates.filter(x=>x!==id);state.selectedWorkerId=w.id;log('Nueva contratación',`${c.name} se une como ${c.roleLabel.toLowerCase()}. Coste de contratación: ${c.hireCost} oro; salario ${c.wage}/día.`);save();render();toast(`${c.name} se une a la plantilla`)}
function refreshCandidates(){if(state.gold<8)return toast('Necesitas 8 de oro');state.gold-=8;const hired=new Set(state.staff.map(w=>w.catalogId||String(w.id).split('-')[0]));let pool=CANDIDATE_CATALOG.filter(c=>!hired.has(c.id)&&state.reputation>=c.minRep);if(pool.length<3)pool=CANDIDATE_CATALOG.filter(c=>state.reputation>=c.minRep);state.candidates=shuffle(pool.map(x=>x.id)).slice(0,Math.min(3,pool.length));log('Mercado laboral','Pagaste 8 de oro a un reclutador. La reputación de la taberna determina la calidad de las candidatas disponibles.');save();render()}
function shuffle(a){return[...a].sort(()=>Math.random()-.5)}
function selectedWorker(){return state.staff.find(w=>w.id===state.selectedWorkerId)||state.staff[0]}
function selectWorker(id){state.selectedWorkerId=id;save();render()}
function talkWorker(){const w=selectedWorker();if(!w)return;if(w.talkedDay===state.day)return toast('Ya hablaste con ella hoy');w.morale=clamp(w.morale+rand(6,12),0,100);w.loyalty=clamp((w.loyalty??60)+2,0,100);w.talkedDay=state.day;log('Conversación',`Hablaste con ${w.name}. Su moral y lealtad mejoraron.`);save();render();toast(`${w.name}: moral y lealtad +`)}
function giftWorker(){const w=selectedWorker();if(!w)return;if(w.giftedDay===state.day)return toast('Ya le diste un regalo hoy');if(state.gold<10)return toast('El regalo cuesta 10 de oro');state.gold-=10;w.morale=clamp(w.morale+8,0,100);w.loyalty=clamp((w.loyalty??60)+5,0,100);w.giftedDay=state.day;log('Regalo',`Diste un pequeño regalo a ${w.name}. Lealtad +5.`);save();render();toast(`${w.name}: lealtad +5`)}
function validPosts(w){return w.role==='cook'?['cocina','despensa']:w.roleLabel==='Anfitriona'?['recepcion','salon','barra']:['salon','barra','recepcion']}function setAssignment(workerId,post){const w=state.staff.find(x=>x.id===workerId);if(!w||!validPosts(w).includes(post))return;w.assignment=post;w.active=true;log('Asignación',`${w.name} ahora trabajará en ${assignmentLabel(post).toLowerCase()}.`);save();render();toast(`${w.name}: ${assignmentLabel(post)}`)}function assignWorker(){const w=selectedWorker();if(!w)return;const options=validPosts(w);const i=options.indexOf(w.assignment);setAssignment(w.id,options[(i+1)%options.length])}
function assignmentLabel(a){return POST_DEFS[a]?.label||'Auto'}
function trainWorker(){const w=selectedWorker();if(!w)return;if(state.gold<18)return toast('Entrenar cuesta 18 de oro');if(w.energy<35)return toast(`${w.name} está demasiado cansada`);state.gold-=18;w.energy=trainerInfinite()?100:clamp(w.energy-18,0,100);w.xp+=35;const stat=['service','charisma','speed','stamina'][rand(0,3)];w[stat]=clamp(w[stat]+rand(1,3),1,99);levelCheck(w);log('Entrenamiento',`${w.name} entrenó ${stat}. Coste: 18 oro.`);save();render();toast(`${w.name} ganó experiencia`)}
function levelCheck(w){while(w.xp>=w.level*100){w.xp-=w.level*100;w.level++;w.service=clamp(w.service+2,1,99);w.speed=clamp(w.speed+1,1,99);w.stamina=clamp(w.stamina+1,1,99);w.charisma=clamp(w.charisma+1,1,99);log('Subida de nivel',`${w.name} alcanza nivel ${w.level}.`)}}
function toggleRest(){const w=selectedWorker();if(!w)return;w.active=!w.active;log(w.active?'Vuelve al turno':'Descanso',`${w.name} ${w.active?'vuelve a estar activa':'descansará durante la próxima jornada'}.`);save();render()}
function dismissSelected(){const w=selectedWorker();if(!w)return;if(state.staff.length<=1)return toast('Necesitas al menos una trabajadora');confirmAction('Despedir trabajadora',`¿Despedir a ${w.name}? No recuperarás costes de contratación.`,()=>{state.staff=state.staff.filter(x=>x.id!==w.id);state.selectedWorkerId=state.staff[0]?.id||null;log('Fin de contrato',`${w.name} deja la taberna.`);save();render()})}
function confirmAction(title,text,action){modalAction=action;$('#modalTitle').textContent=title;$('#modalText').textContent=text;$('#confirmModal').classList.add('show');$('#confirmModal').setAttribute('aria-hidden','false')}
function closeModal(){modalAction=null;$('#confirmModal').classList.remove('show');$('#confirmModal').setAttribute('aria-hidden','true')}
function customerMix(visitors){let weights={peasants:.34,merchants:.2,adventurers:.2,guards:.17,nobles:.09};if(state.forecast.id==='market'){weights.merchants+=.18;weights.peasants-=.08}if(state.forecast.id==='caravan'){weights.adventurers+=.18;weights.peasants-=.08}if(state.forecast.id==='guard'){weights.guards+=.2;weights.peasants-=.1}if(state.reputation<20){weights.nobles=.02;weights.peasants+=.07}else if(state.reputation>45){weights.nobles+=.08;weights.merchants+=.03}const keys=Object.keys(weights),sum=keys.reduce((a,k)=>a+weights[k],0),counts=Object.fromEntries(keys.map(k=>[k,0]));for(let i=0;i<visitors;i++){let r=Math.random()*sum;for(const k of keys){r-=weights[k];if(r<=0){counts[k]++;break}}}return counts}
function eventForDay(customers){const r=Math.random();if(r<.1){const tip=rand(8,20);state.gold+=tip;state.reputation++;return`Un mercader satisfecho dejó ${tip} oro extra.`}if(r<.18){const loss=Math.min(Math.max(0,state.gold),rand(6,14));state.gold-=loss;state.reputation=Math.max(0,state.reputation-1);return`Una pelea rompió vajilla. Reparaciones: ${loss} oro.`}if(r<.25&&customers>=7){state.reputation+=2;return'Un bardo compuso una canción sobre la casa. +2 reputación.'}if(r<.31&&state.food>4){const loss=Math.min(state.food,rand(2,5));state.food-=loss;return`Ratas en la despensa: perdiste ${loss} raciones.`}if(r<.36){state.reputation++;return'Un grupo de aventureros tomó la taberna como punto de reunión. +1 reputación.'}return null}
function openTavern(){if(activeStaff().length===0)return toast('No tienes personal activo');const readiness=operationalReadiness(),repPull=4+state.reputation*.34+hospitalityPower()*.035,random=rand(-2,6),fmod=state.forecast?.mod||1,coverageMod=readiness.score/100;let visitors=Math.round((repPull+random)*demandModifier()*fmod*(.82+coverageMod*.18));visitors=clamp(visitors,1,capacity());const mix=customerMix(visitors),service=serviceScore(visitors),barBoost=hasPost('barra')?1:.72,kitchenBoost=hasPost('cocina')?1:.38,receptionBoost=hasPost('recepcion')?1.08:1,aleChance=clamp((.62+state.reputation*.004+avg(servers(),'charisma')*.0015+(hasAbility('extraAle')?.06:0)-Math.max(0,state.prices.ale-4)*.055)*barBoost,.1,.95),foodChance=clamp((.22+kitchenPower()*.007+avg(cooks(),'service')*.001+(hasAbility('special')?.02:0)-Math.max(0,state.prices.meal-7)*.04)*kitchenBoost,.04,.9);let aleSold=0,mealsSold=0,unhappy=0;for(let i=0;i<visitors;i++){if(chance(aleChance)){if(state.ale>0){state.ale--;aleSold++}else unhappy++}if(chance(foodChance)){if(state.food>0){state.food--;mealsSold++}else unhappy++}if(service<.78&&chance(.3))unhappy++}const baseRevenue=aleSold*state.prices.ale+mealsSold*state.prices.meal;const vipIncome=hasAbility('vip')&&hasPost('recepcion')?Math.round(mix.nobles*rand(2,4)*receptionBoost):0;const specialIncome=hasAbility('special')&&hasPost('cocina')&&mealsSold>=2&&chance(.38)?rand(7,15)+Math.round(mealsSold*.45):0;const salary=wages(),roomIncome=state.upgrades.rooms>0?rand(0,state.upgrades.rooms*5):0;const revenue=baseRevenue+vipIncome+specialIncome+roomIncome,expenses=salary,operatingNet=revenue-expenses;state.gold+=operatingNet;let repDelta=0;if(unhappy===0&&service>=.95)repDelta+=2;else if(unhappy<=2&&service>=.78)repDelta++;else if(unhappy>=5)repDelta-=2;else if(unhappy>=3)repDelta--;if(readiness.missing.length>=2)repDelta--;if(hasAbility('warm')&&hasPost('salon')&&service>=.82)repDelta+=chance(.35)?1:0;if(state.prices.ale>=8||state.prices.meal>=13)repDelta--;state.reputation=clamp(state.reputation+repDelta,0,100);let spoilage=0;const spoilChance=.4*(hasAbility('mise')?.45:1)*(hasPost('despensa')?.55:1);if(state.food>cellarSoftCap()&&chance(spoilChance)){spoilage=Math.min(state.food-cellarSoftCap(),hasAbility('mise')?1:rand(1,3));state.food-=spoilage}const before=state.gold,event=eventForDay(visitors),eventGold=state.gold-before,finalNet=operatingNet+eventGold;const leavers=[],staffSnapshot=[];for(const w of state.staff){staffSnapshot.push({id:w.id,name:w.name,assignment:w.assignment,active:w.active,energy:Math.round(w.energy)});if(w.active){const postLoad={salon:1.15,barra:1.1,recepcion:.9,cocina:1.18,despensa:.78}[w.assignment]||1;const drain=Math.round(rand(8,15)*(1.15-w.stamina/200)*postLoad);w.energy=clamp(w.energy-drain,0,100);w.morale=clamp(w.morale+(service>.9?2:service<.65?-3:0),0,100);w.loyalty=clamp((w.loyalty??60)+(service>.9?1:service<.65?-1:0)+(w.energy<20?-1:0),0,100);w.xp+=rand(8,15);levelCheck(w)}else{w.energy=clamp(w.energy+rand(28,42),0,100);w.morale=clamp(w.morale+2,0,100);w.loyalty=clamp((w.loyalty??60)+1,0,100)}if(w.id!=='elena-main'&&(w.loyalty??60)<18&&chance(.12))leavers.push(w)}if(leavers.length){state.staff=state.staff.filter(w=>!leavers.some(x=>x.id===w.id));for(const w of leavers)log('Renuncia',`${w.name} abandonó la taberna por su baja lealtad.`);if(!state.staff.some(w=>w.id===state.selectedWorkerId))state.selectedWorkerId=state.staff[0]?.id||null}state.lifetime.customers+=visitors;state.lifetime.revenue+=revenue;state.lifetime.expenses+=expenses;state.lifetime.profit+=finalNet;const record={day:state.day,visitors,aleSold,mealsSold,revenue,expenses,salary,roomIncome,vipIncome,specialIncome,net:finalNet,unhappy,forecast:state.forecast.label,mix,readiness:readiness.score,missingPosts:readiness.missing,staffSnapshot};state.lastDay=record;state.financeHistory.push(record);state.financeHistory=state.financeHistory.slice(-30);state.customerHistory.push({day:state.day,mix,visitors});state.customerHistory=state.customerHistory.slice(-30);let text=`${visitors} clientes · ${aleSold} cervezas · ${mealsSold} platos · ingresos ${revenue} · gastos ${expenses} · balance ${finalNet>=0?'+':''}${finalNet}.`;if(readiness.missing.length)text+=` Puestos sin cubrir: ${readiness.missing.map(assignmentLabel).join(', ')}.`;if(vipIncome)text+=` Atención VIP +${vipIncome}.`;if(specialIncome)text+=` Especial de cocina +${specialIncome}.`;if(repDelta)text+=` Reputación ${repDelta>0?'+':''}${repDelta}.`;if(event)text+=` Evento: ${event}`;if(spoilage)text+=` Merma: ${spoilage} raciones.`;log(`Jornada ${state.day} · ${state.forecast.label}`,text);state.day++;state.forecast=makeForecast();save();render();toast(`Jornada cerrada: ${finalNet>=0?'+':''}${finalNet} oro`)}
function render(){renderHud();renderFocus();renderScene();renderSummary();renderRecruitment();renderTavern();renderStaff();renderCustomers();renderStock();renderFinance();renderUpgrades();renderRumors();renderLog();renderButtons();renderTrainer()}
function renderHud(){$('#day').textContent=state.day;$('#season').textContent=season();$('#gold').textContent=state.gold;$('#reputation').textContent=state.reputation;$('#occupancy').textContent=`${state.lastDay?.visitors||0}/${capacity()}`}
