function renderStaff(){const summary=$('#summaryRoster');if(summary)summary.innerHTML=state.staff.slice(0,6).map(w=>`<button class="summary-worker ${w.active?'':'resting'}" data-summary-worker="${w.id}"><img src="${w.portrait||w.sprite}" alt="${w.name}"><div><strong>${w.name}</strong><small>${w.roleLabel} · Nv. ${w.level}</small><span>${w.active?assignmentLabel(w.assignment):'Descanso'} · ${Math.round(w.energy)}% energía</span></div></button>`).join('');$('#staffRoster').innerHTML=state.staff.map(w=>`<article class="staff-card ${w.active?'':'resting'}"><img src="${w.portrait||w.sprite}" alt="${w.name}"><div class="staff-card-copy"><div class="candidate-title"><h3>${w.name}</h3><span class="rarity-tag ${w.rarityClass||'common'}">${w.rarity||'Común'}</span></div><small>${w.roleLabel} · Nv. ${w.level} · ${w.active?assignmentLabel(w.assignment):'Descanso'}</small><div class="worker-state"><span>${mood(w)}</span><span>Energía ${Math.round(w.energy)}%</span><span>Lealtad ${Math.round(w.loyalty??60)}%</span><span>${w.wage}/día</span></div><div class="candidate-skill compact">${w.ability||'Sin especialidad'}</div><div class="bar"><i style="width:${Math.min(100,(w.xp/(w.level*100))*100)}%"></i></div></div><div class="staff-card-actions"><button data-select="${w.id}">Ver expediente</button><button data-active="${w.id}">${w.active?'Mandar a descanso':'Activar turno'}</button></div></article>`).join('');document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selectWorker(b.dataset.select);switchTab('summary')});document.querySelectorAll('[data-active]').forEach(b=>b.onclick=()=>{state.selectedWorkerId=b.dataset.active;toggleRest()});document.querySelectorAll('[data-summary-worker]').forEach(b=>b.onclick=()=>selectWorker(b.dataset.summaryWorker))}
