  if(state.ale<=0&&state.food<=0)return toast('No tienes inventario para abrir');
  const ready=operationalReadiness(),base=Math.round((capacity()*1.72+state.reputation*.1+hospitalityPower()*.045)*demandModifier()*(state.forecast?.mod||1));
  const target=clamp(base,Math.max(7,capacity()),capacity()*4);
  liveShift={day:state.day,tick:0,totalTicks:120,speed:1,paused:false,finished:false,targetArrivals:target,arrivals:0,guests:[],served:0,lost:0,revenue:0,tips:0,aleSold:0,mealsSold:0,unhappy:0,maxOccupancy:0,totalWait:0,satSum:0,satCount:0,eventCost:0,repBonus:0,events:[],log:[],mix:{peasants:0,merchants:0,adventurers:0,guards:0,nobles:0},postTicks:Object.fromEntries(state.staff.map(w=>[w.id,{}])),regularsGained:[]};
  $('#liveShiftOverlay').classList.add('open');$('#liveShiftOverlay').classList.remove('finished');$('#liveShiftOverlay').setAttribute('aria-hidden','false');document.body.style.overflow='hidden';
