  state.gold+=net;let repDelta=L.repBonus;if(avgSat>.95&&lostRate<.12)repDelta+=2;else if(avgSat>.78&&lostRate<.25)repDelta+=1;if(lostRate>.34)repDelta-=2;else if(lostRate>.22)repDelta-=1;if(state.prices.ale>=8||state.prices.meal>=13)repDelta--;state.reputation=clamp(state.reputation+repDelta,0,100);
