function syncLegacyStock(){state.ale=state.inventory.beer||0;state.food=state.inventory.stew||0;state.prices.ale=state.productPrices.beer;state.prices.meal=state.productPrices.stew}
function ensureV07State(){
  const needsV07=!state.inventory;
  if(!state.inventory)state.inventory={beer:Number(state.ale)||0,wine:0,mead:0,stew:Number(state.food)||0,roast:0,cheese:0};
  for(const id of Object.keys(PRODUCTS))if(state.inventory[id]==null)state.inventory[id]=0;
  if(!state.productPrices)state.productPrices={beer:state.prices?.ale??4,wine:7,mead:9,stew:state.prices?.meal??7,roast:11,cheese:8};
  if(!state.menuEnabled)state.menuEnabled={beer:true,wine:true,mead:true,stew:true,roast:true,cheese:true};
  if(!state.avgCost)state.avgCost=Object.fromEntries(Object.values(PRODUCTS).map(p=>[p.id,p.buyCost/p.buyPack]));
  if(!state.supplier||!SUPPLIERS[state.supplier])state.supplier='local';
  if(!Array.isArray(state.candidates)||!state.candidates.length||needsV07||state.candidates.some(c=>typeof c==='string')){state.candidates=generateCandidates(3);state.marketEvent=marketEventFor(state.candidates)}
  else state.candidates=state.candidates.filter(Boolean);
  if(needsV07){log('Actualización V0.7','La economía ahora funciona por productos, proveedores y márgenes. El mercado laboral genera candidatas nuevas con rarezas, incluyendo Prodigios y Genios excepcionalmente raras.');}
  state.schemaVersion=7;syncLegacyStock();save();
}
function candidateByLegacyId(id){return CANDIDATE_CATALOG.find(c=>c.id===id)}
function rarityRoll(){const r=Math.random();if(r<.001)return'genius';if(r<.01)return'prodigy';if(r<.06)return'elite';if(r<.18)return'expert';if(r<.45)return'competent';return'common'}
function pick(arr){return arr[rand(0,arr.length-1)]}
function generateCandidate(){
  const key=rarityRoll(),d=RARITY_DEFS[key],role=chance(.66)?'server':'cook',roleLabel=role==='cook'?'Cocinera':(chance(.18)?'Anfitriona':'Camarera'),ability=pick(role==='cook'?COOK_ABILITIES:SERVER_ABILITIES),stats={service:rand(d.min,d.max),charisma:rand(d.min,d.max),speed:rand(d.min,d.max),stamina:rand(d.min,d.max)};
  if(role==='cook')stats.cooking=rand(d.min,d.max);
  const name=pick(PROCEDURAL_NAMES),age=rand(22,39),outfit=pick(OUTFITS[key]),wage=rand(...d.wage),hireCost=rand(...d.hire),assignment=role==='cook'?'cocina':(roleLabel==='Anfitriona'?'recepcion':(chance(.45)?'barra':'salon'));
  return{id:`proc-${Date.now()}-${Math.random().toString(36).slice(2,9)}`,instanceId:`cand-${Date.now()}-${Math.random().toString(36).slice(2,10)}`,catalogId:null,name,age,role,roleLabel,portrait:pick(PORTRAIT_POOL),sprite:pick(PORTRAIT_POOL),wage,hireCost,...stats,rarity:d.label,rarityClass:d.className,rarityKey:key,trait:pick(TRAITS),ability:ability.name,abilityId:ability.id,abilityText:ability.text,assignment,minRep:0,outfit,procedural:true};
}
function generateCandidates(n=3){const out=[];for(let i=0;i<n;i++)out.push(generateCandidate());return out}
function marketEventFor(list){const g=list.find(c=>c.rarityKey==='genius');if(g)return{kind:'genius',text:`Una candidata casi imposible ha llegado a Brumavieja: ${g.name}, catalogada como GENIO. Los mejores establecimientos del reino matarían por contratarla.`};const p=list.find(c=>c.rarityKey==='prodigy');if(p)return{kind:'prodigy',text:`Rumor extraordinario: ${p.name}, una trabajadora Prodigio, está buscando empleo por un tiempo muy limitado.`};return null}
function candidateById(id){return state.candidates.find(c=>c.instanceId===id||c.id===id)||CANDIDATE_CATALOG.find(c=>c.id===id)}
function hireCandidate(id){const c=candidateById(id);if(!c)return;if(state.gold<c.hireCost)return toast('No tienes suficiente oro');state.gold-=c.hireCost;const w=makeWorker(c,{id:`worker-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,catalogId:c.id,morale:rand(68,86),energy:100,loyalty:rand(55,76),outfit:c.outfit,age:c.age,rarityKey:c.rarityKey});state.staff.push(w);state.candidates=state.candidates.filter(x=>x!==c);state.marketEvent=marketEventFor(state.candidates);state.selectedWorkerId=w.id;log('Nueva contratación',`${c.name}, ${c.rarity.toLowerCase()}, se une como ${c.roleLabel.toLowerCase()}. Contrato ${c.hireCost} oro; salario ${c.wage}/día.`);save();render();toast(`${c.name} se une a la plantilla`)}
function refreshCandidates(){if(state.gold<8)return toast('Necesitas 8 de oro');state.gold-=8;state.candidates=generateCandidates(chance(.22)?4:3);state.marketEvent=marketEventFor(state.candidates);const special=state.marketEvent;log('Mercado laboral',special?special.text:'El reclutador trajo una nueva selección de candidatas. Cada renovación es diferente.');save();render();if(special)toast(special.kind==='genius'?'¡CANDIDATA GENIO!':'¡Apareció una Prodigio!')}
function rarityPower(w){const key=w.rarityKey||Object.keys(RARITY_DEFS).find(k=>RARITY_DEFS[k].label===w.rarity);return RARITY_DEFS[key]?.power||1}
function workerEfficiency(w){const energy=.55+.45*(w.energy/100),morale=.7+.3*(w.morale/100),loyalty=.85+.15*((w.loyalty??60)/100),level=1+(w.level-1)*.04;return energy*morale*loyalty*level*rarityPower(w)}
function supplierCost(p){const s=SUPPLIERS[state.supplier]||SUPPLIERS.local;return Math.max(1,Math.round(p.buyCost*s.factor))}
function supplierPack(p){const s=SUPPLIERS[state.supplier]||SUPPLIERS.local;return Math.max(1,Math.round(p.buyPack*s.stockBonus))}
function buyProduct(id){const p=PRODUCTS[id];if(!p)return;if(state.reputation<p.minRep)return toast(`Requiere reputación ${p.minRep}`);const cost=supplierCost(p),amount=supplierPack(p);if(state.gold<cost)return toast('No tienes suficiente oro');const currentTotal=Object.values(state.inventory).reduce((a,n)=>a+n,0);if(currentTotal+amount>cellarSoftCap()*2.4)return toast('No tienes espacio de almacenamiento suficiente');const prevQty=state.inventory[id]||0,unitCost=cost/amount;state.gold-=cost;state.inventory[id]=prevQty+amount;state.avgCost[id]=prevQty?((state.avgCost[id]*prevQty)+(unitCost*amount))/(prevQty+amount):unitCost;syncLegacyStock();log('Compra de suministros',`${p.name}: +${amount} por ${cost} oro mediante ${SUPPLIERS[state.supplier].name}.`);save();render();toast(`${p.short}: +${amount}`)}
function setSupplier(id){const s=SUPPLIERS[id];if(!s)return;if(state.reputation<s.minRep)return toast(`Requiere reputación ${s.minRep}`);state.supplier=id;save();render();toast(`Proveedor: ${s.name}`)}
function changeProductPrice(id,delta){const p=PRODUCTS[id];if(!p)return;state.productPrices[id]=clamp((state.productPrices[id]??p.defaultPrice)+delta,1,30);syncLegacyStock();save();render()}
function toggleMenuProduct(id){const p=PRODUCTS[id];if(!p||state.reputation<p.minRep)return;state.menuEnabled[id]=!state.menuEnabled[id];save();render()}
function activeMenu(category){return Object.values(PRODUCTS).filter(p=>p.category===category&&state.menuEnabled[p.id]&&state.reputation>=p.minRep)}
function weightedOrder(list){const options=list.filter(([id])=>state.menuEnabled[id]&&state.reputation>=PRODUCTS[id].minRep);if(!options.length)return null;let total=options.reduce((a,x)=>a+x[1],0),r=Math.random()*total;for(const [id,w] of options){r-=w;if(r<=0)return id}return options[0][0]}
function menuDemandPenalty(){let pen=0,bonus=0;for(const p of Object.values(PRODUCTS)){if(!state.menuEnabled[p.id]||state.reputation<p.minRep)continue;const price=state.productPrices[p.id],ratio=price/p.defaultPrice;if(ratio>1.7)pen+=.035;if(ratio<.85)bonus+=.015}return clamp(1-pen+bonus,.76,1.12)}
function demandModifier(){const decor=1+(state.upgrades.decor-1)*.025;return clamp(menuDemandPenalty()*decor,.4,1.3)}
