function liveShiftSnapshot(){
  if(!liveShift||liveShift.finished)return null;
  const out={...liveShift};
  out.shortageWarnings=[...(liveShift.shortageWarnings||[])];
  out.pendingDecisionId=liveShift.pendingDecision?.id||null;
  delete out.pendingDecision;
  return out
}
function clearLiveShiftSnapshot(){try{localStorage.removeItem(LIVE_SHIFT_KEY)}catch{}}
function persistLiveShift(){
  if(!liveShift||liveShift.finished){clearLiveShiftSnapshot();return}
  try{save();localStorage.setItem(LIVE_SHIFT_KEY,JSON.stringify(liveShiftSnapshot()))}catch{}
}
function presentV09Decision(ev){
  if(!ev)return;
  const modal=$('#eventDecisionModal');
  $('#eventDecisionTitle').textContent=ev.title;
  $('#eventDecisionText').textContent=ev.text;
  $('#eventDecisionMeta').textContent=ev.meta;
  $('#eventDecisionChoices').innerHTML=ev.choices.map((c,i)=>{const locked=c.requires==='vip'&&v09Level('vip')<=0;return `<button class="event-choice ${c.risk?'risk':''} ${c.premium?'premium':''}" data-event-choice="${i}" ${locked?'disabled':''}><b>${c.label}</b><small>${locked?'Requiere Salón VIP.':c.detail}</small></button>`}).join('');
  modal.classList.add('open');modal.setAttribute('aria-hidden','false');
  document.querySelectorAll('[data-event-choice]').forEach(b=>b.onclick=()=>resolveV09Decision(Number(b.dataset.eventChoice)))
}
function restoreLiveShift(){
  try{
    const raw=localStorage.getItem(LIVE_SHIFT_KEY);if(!raw)return false;
    const snap=JSON.parse(raw);
    if(!snap||snap.finished||Number(snap.day)!==Number(state.day)){clearLiveShiftSnapshot();return false}
    snap.shortageWarnings=new Set(Array.isArray(snap.shortageWarnings)?snap.shortageWarnings:[]);
    snap.productSales=snap.productSales||Object.fromEntries(Object.keys(PRODUCTS).map(id=>[id,{qty:0,revenue:0,cogs:0}]));
    snap.postTicks=snap.postTicks||Object.fromEntries(state.staff.map(w=>[w.id,{}]));
    snap.regularsGained=Array.isArray(snap.regularsGained)?snap.regularsGained:[];
    snap.events=Array.isArray(snap.events)?snap.events:[];
    snap.log=Array.isArray(snap.log)?snap.log:[];
    snap.directSpend=Number(snap.directSpend||0);
    snap.inventorySpend=Number(snap.inventorySpend||0);
    snap.pendingDecision=snap.pendingDecisionId?V09_DECISION_EVENTS.find(e=>e.id===snap.pendingDecisionId)||null:null;
    liveShift=snap;
    $('#liveShiftOverlay').classList.add('open');$('#liveShiftOverlay').classList.remove('finished');$('#liveShiftOverlay').setAttribute('aria-hidden','false');
    document.body.style.overflow='hidden';
    renderLiveShift();
    if(liveShift.pendingDecision){liveShift.paused=true;presentV09Decision(liveShift.pendingDecision)}
    clearInterval(liveTimer);liveTimer=setInterval(liveFrame,1000);
    showLiveBanner('JORNADA RECUPERADA · continúas donde la dejaste');
    return true
  }catch{clearLiveShiftSnapshot();return false}
}


